import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs.setdefault(name, {})[p['id']] = (p.get('requestedVersion',''), p.get('resolvedVersion',''))
    return pkgs

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for pkg in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bv = b.get(proj,{}).get(pkg, (None,None))
        av = a.get(proj,{}).get(pkg, (None,None))
        if bv[1] != av[1]:
            changes.append((proj, pkg, bv[1], av[1]))
        else:
            unchanged.append((proj, pkg, av[1]))

print('=== CHANGES ===')
for c in changes:
    print(f'  {c[0]}: {c[1]} {c[2]} -> {c[3]}')
if not changes:
    print('  (none)')

print()
print(f'=== UNCHANGED: {len(unchanged)} package-project pairs ===')
for u in unchanged:
    print(f'  {u[0]}: {u[1]} @ {u[2]}')
"

